function mask(t,id){if(!t)return t;var n=D.name(id.replace(/r$/,''));n.split(' ').forEach(function(w){if(w.length<3||SUITW.indexOf(w)>=0)return;t=t.replace(new RegExp('(^|[^а-яёА-ЯЁ])('+root(w)+')(?![а-яё])','g'),'$1«…»');});return t.replace(/«…»\s+«…»/g,'«…»');}
