if(TM.length>=5)T.push({id:'terms',title:'Понятия и определения',fmt:'термин → смысл',desc:'Назван термин или приём из урока. Выберите его объяснение.',mode:'mcq',count:Math.min(TM.length*2,24),
 gen:function(){var x=P(TM);var w=SH(TM.filter(function(y){return y.term!==x.term;})).slice(0,3).map(function(y){return cut(y.def,220);});
  if(Math.random()<0.5)return mcq('«'+x.term+'». Что это значит?',cut(x.def,220),w,{e:x.def});
  return mcq('Какому понятию соответствует объяснение?',x.term,SH(TM.filter(function(y){return y.term!==x.term;})).slice(0,3).map(function(y){return y.term;}),{story:cut(x.def,300)});}});
